const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch(); const p = await b.newPage({ viewport: { width: 375, height: 812 }, hasTouch: true });
  const errs = []; p.on('pageerror', e => errs.push(e.message)); p.on('console', m => m.type()==='error' && !m.text().includes('Failed to load resource') && errs.push(m.text()));
  await p.goto('file://' + process.argv[2]);
  const sum = () => p.$eval('.sum-fig', e => e.textContent);
  console.log('initial', await sum());
  await p.click('.check:not(.on)'); console.log('after tick', await sum(), await p.$eval('.check.pop', e=>e.getAttribute('aria-label')));
  await p.click('.check.on'); console.log('after untick', await sum());
  // add habit
  await p.click('.tab-add'); await p.fill('#fName', 'Stretch 5 min'); await p.click('[data-action=f-emoji][data-v="💪"]');
  await p.click('[data-action=f-mode][data-v=week]'); await p.click('#habitForm button[type=submit]'); await p.waitForTimeout(400);
  console.log('after add', await sum(), await p.$eval('#toastMsg', e=>e.textContent));
  // empty name validation
  await p.click('.tab-add'); await p.click('#habitForm button[type=submit]'); console.log('err', await p.$eval('.err-msg', e=>e.textContent));
  await p.keyboard.press('Escape'); await p.waitForTimeout(300);
  // persistence
  await p.reload(); console.log('after reload', await sum(), (await p.$$('.row')).length, 'rows');
  // past day select
  await p.click('.day:not(.sel):not(:disabled)'); console.log('past day', await p.$eval('.sum-label', e=>e.textContent), await sum());
  // detail + calendar toggle
  await p.click('.row-main'); const before = await p.$eval('.d-stat strong', e=>e.textContent);
  await p.click('.cal button.td'); console.log('streak before/after toggling today', before, await p.$eval('.d-stat strong', e=>e.textContent));
  await p.click('[data-action=delete]'); await p.waitForTimeout(300); const n1 = (await p.$$('.row')).length;
  await p.click('#toastAct'); console.log('rows after delete/undo', n1, (await p.$$('.row')).length);
  for (const t of ['progress','habits','settings']) { await p.click(`.tab[data-tab=${t}]`); }
  console.log('errors', errs);
  await b.close();
})();
EOF
